const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const obolon = ee.Geometry.Polygon([[
    [30.470, 50.520],
    [30.530, 50.520],
    [30.530, 50.490],
    [30.470, 50.490],
    [30.470, 50.520]
  ]]);

  const march2022 = ee.DateRange('2022-03-01', '2022-03-31');
  const may2022 = ee.DateRange('2022-05-01', '2022-05-31');

  // 2. Data Acquisition - VIIRS Nighttime Lights
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VNP46A2')
    .select(['DNB_BRDF-Corrected_NTL', 'QF_Cloud_Mask']);

  const marchCol = viirs.filterDate(march2022).filterBounds(obolon);
  const mayCol = viirs.filterDate(may2022).filterBounds(obolon);

  // Check collection sizes
  const marchSize = marchCol.size().getInfo();
  const maySize = mayCol.size().getInfo();

  console.log(`March 2022 Images: ${marchSize}`);
  console.log(`May 2022 Images: ${maySize}`);

  if (marchSize === 0 || maySize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create monthly composites and mask poor quality
  function maskPoorQuality(image) {
    const qa = image.select('QF_Cloud_Mask');
    // Keep only highest quality pixels (clear, no clouds)
    const mask = qa.bitwiseAnd(3).eq(0); // Bits 0-1 = 00 (clear)
    return image.select('DNB_BRDF-Corrected_NTL').updateMask(mask);
  }

  const marchComposite = marchCol.map(maskPoorQuality).median();
  const mayComposite = mayCol.map(maskPoorQuality).median();

  // 4. Calculate mean radiance values
  const marchStats = marchComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: obolon,
    scale: 1000,
    maxPixels: 1e9
  });

  const mayStats = mayComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: obolon,
    scale: 1000,
    maxPixels: 1e9
  });

  const marchRad = marchStats.get('DNB_BRDF-Corrected_NTL').getInfo();
  const mayRad = mayStats.get('DNB_BRDF-Corrected_NTL').getInfo();

  // Check for valid pixel counts
  const marchCount = marchComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: obolon,
    scale: 1000,
    maxPixels: 1e9
  }).get('DNB_BRDF-Corrected_NTL').getInfo();

  const mayCount = mayComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: obolon,
    scale: 1000,
    maxPixels: 1e9
  }).get('DNB_BRDF-Corrected_NTL').getInfo();

  console.log(`March radiance: ${marchRad ? marchRad.toFixed(4) : 'null'}, Pixels: ${marchCount}`);
  console.log(`May radiance: ${mayRad ? mayRad.toFixed(4) : 'null'}, Pixels: ${mayCount}`);

  // 5. Validation & Final Answer
  if (marchCount === 0 || mayCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (marchRad === null || mayRad === null || 
             isNaN(marchRad) || isNaN(mayRad) ||
             marchRad < 0 || mayRad < 0) {
    console.log("<answer>C3</answer>");
  } else if (mayRad < marchRad) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
